/* Progressive enhancement: contact links and navigation also work without JS. */
(() => {
  const dock = document.querySelector('.contact-dock');
  const header = document.querySelector('#header');
  if (!dock || !header || !('IntersectionObserver' in window)) return;
  dock.setAttribute('data-floating', '');
  const observer = new IntersectionObserver(([entry]) => {
    const visible = !entry.isIntersecting && entry.boundingClientRect.bottom <= 0;
    dock.classList.toggle('is-visible', visible);
    // A hidden dock must not leave an invisible link in the keyboard tab order.
    dock.inert = !visible;
  });
  dock.inert = true;
  observer.observe(header);
})();
